import{_ as t,o,c as d,ao as i}from"./chunks/framework.DAbzcW3k.js";const y=JSON.parse('{"title":"Inputs","description":"","frontmatter":{},"headers":[],"relativePath":"inputs.md","filePath":"inputs.md","lastUpdated":null}'),a={name:"inputs.md"};function r(s,e,l,n,c,h){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="Inputs" tabindex="-1">Inputs <a class="header-anchor" href="#Inputs" aria-label="Permalink to &quot;Inputs {#Inputs}&quot;">​</a></h1><p>Every input is optional. A method&#39;s <code>_model</code> is the 3D volume and its <code>_data</code> is the measured dataset for the same method.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Input</th><th style="text-align:right;">Formats</th><th style="text-align:right;">Loaded as</th></tr></thead><tbody><tr><td style="text-align:right;"><code>MT_model</code></td><td style="text-align:right;">ModEM/WS <code>.rho</code>, jif3D <code>.nc</code></td><td style="text-align:right;">Resistivity volume</td></tr><tr><td style="text-align:right;"><code>MT_data</code></td><td style="text-align:right;">ModEM <code>.dat</code>, jif3D <code>.nc</code></td><td style="text-align:right;">Georeferences the mesh; <strong>Show Data</strong> draws the site locations</td></tr><tr><td style="text-align:right;"><code>gravity_model</code></td><td style="text-align:right;"><code>.xyz</code>, <code>.vox</code>, jif3D <code>.nc</code></td><td style="text-align:right;">Density volume, displayed in g/cc</td></tr><tr><td style="text-align:right;"><code>gravity_data</code></td><td style="text-align:right;"><code>.xyz</code>, jif3D <code>.nc</code> (mGal)</td><td style="text-align:right;"><strong>Show Data</strong> draws the survey points at their own elevation</td></tr><tr><td style="text-align:right;"><code>magnetic_model</code></td><td style="text-align:right;"><code>.xyz</code>, <code>.vox</code>, jif3D <code>.nc</code></td><td style="text-align:right;">Susceptibility volume</td></tr><tr><td style="text-align:right;"><code>magnetic_data</code></td><td style="text-align:right;"><code>.xyz</code>, jif3D <code>.nc</code> (nT)</td><td style="text-align:right;"><strong>Show Data</strong> draws the survey points</td></tr><tr><td style="text-align:right;"><code>seismic_data</code></td><td style="text-align:right;">SEG-Y, one path or a list</td><td style="text-align:right;">Seismic curtain and model drape per line</td></tr><tr><td style="text-align:right;"><code>shapefiles</code></td><td style="text-align:right;"><code>.shp</code></td><td style="text-align:right;">Linework, each entry with its own <code>color</code>, <code>width</code> and <code>alpha</code></td></tr></tbody></table><h2 id="What-you-get" tabindex="-1">What you get <a class="header-anchor" href="#What-you-get" aria-label="Permalink to &quot;What you get {#What-you-get}&quot;">​</a></h2><p>What you get depends on what you configure:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Configured</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td style="text-align:right;">Nothing</td><td style="text-align:right;">An empty 3D scene, sized to the shapefiles or seismic line if there are any</td></tr><tr><td style="text-align:right;"><code>MT_model</code> only</td><td style="text-align:right;">The model in its own local coordinates; georeferenced overlays are left out</td></tr><tr><td style="text-align:right;"><code>MT_model</code> + <code>MT_data</code></td><td style="text-align:right;">Georeferenced into <code>coordinate.target_crs</code></td></tr><tr><td style="text-align:right;">A jif3D <code>.nc</code> <code>MT_model</code></td><td style="text-align:right;">Georeferenced on its own, from <code>coordinate.jif3d_crs</code> (default EPSG:3067)</td></tr><tr><td style="text-align:right;">A gravity/magnetic model with an MT model</td><td style="text-align:right;">Resampled onto the MT cells, so the properties compare cell for cell</td></tr><tr><td style="text-align:right;">A gravity/magnetic model without one</td><td style="text-align:right;">Gridded on axes taken from its own coordinates</td></tr></tbody></table><h2 id="jif3D-NetCDF-files" tabindex="-1">jif3D NetCDF files <a class="header-anchor" href="#jif3D-NetCDF-files" aria-label="Permalink to &quot;jif3D NetCDF files {#jif3D-NetCDF-files}&quot;">​</a></h2><p>A <code>.nc</code> file in any model or data slot is read as <a href="https://git.tu-berlin.de/applied-geophysics/jif3d" target="_blank" rel="noreferrer">jif3D</a> output. The property comes from the variable in the file: <code>Conductivity</code> (shown as resistivity), <code>Density</code> or <code>Susceptibility</code> for models; MT impedances, <code>Scalar_gravity</code> or total-field <code>T</code> for data. jif3D meshes are absolute projected metres, so an MT model needs no data file to be placed; set <code>coordinate.jif3d_crs</code> when the inversion was not run in the scene&#39;s CRS.</p><h2 id="Several-seismic-lines" tabindex="-1">Several seismic lines <a class="header-anchor" href="#Several-seismic-lines" aria-label="Permalink to &quot;Several seismic lines {#Several-seismic-lines}&quot;">​</a></h2><p><code>seismic_data</code> takes a list. Each entry is a path, or <code>(path =, label =, line_color =, sample_spacing_m =, top_z_m =)</code>; fields left out use the <code>seismic</code> settings. With <code>seismic.trace_xy = :auto</code>, traces are located from the source, group or CDP headers, whichever is filled in.</p><h2 id="Reading-point-files" tabindex="-1">Reading point files <a class="header-anchor" href="#Reading-point-files" aria-label="Permalink to &quot;Reading point files {#Reading-point-files}&quot;">​</a></h2><p><code>.xyz</code> models and surveys are <code>longitude latitude elevation value</code> records, or easting/northing in any projected CRS. They are reprojected into the project CRS and, for models, resampled onto the scene&#39;s cells.</p><h3 id="Source-CRS-detection" tabindex="-1">Source CRS detection <a class="header-anchor" href="#Source-CRS-detection" aria-label="Permalink to &quot;Source CRS detection {#Source-CRS-detection}&quot;">​</a></h3><p>A file that states no CRS has one worked out for it. Degrees and projected metres never overlap in practice: longitude/latitude is bounded by ±180/±90, while a metric CRS puts survey data tens to hundreds of kilometres from its false origin. A file is therefore read as WGS84 lon/lat or as already being in the project CRS accordingly. When both columns fall inside ±90 and the lon/lat order is ambiguous, the project CRS&#39;s declared area of use decides which column is longitude, so latitude-first files land in the right place too. <code>.prj</code> files and ModEM origins are still read from the file itself.</p>',14)])])}const p=t(a,[["render",r]]);export{y as __pageData,p as default};
